using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// With the default reflection resolver every type resolves, so use a
// source-gen-only context that knows about Person but NOT about int[].
var restricted = new JsonSerializerOptions { TypeInfoResolver = PersonContext.Default };

if (restricted.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? pInfo))
    Console.WriteLine($"TryGet Person: found – {pInfo!.Type.Name}");
else
    Console.WriteLine("TryGet Person: not found");

if (restricted.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrInfo))
    Console.WriteLine($"TryGet int[]: found – {arrInfo!.Type.Name}");
else
    Console.WriteLine("TryGet int[]: not found (as expected)");

// --- types ---

public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;

